diff --git a/cmd/entire/cli/integration_test/hook_logging_test.go b/cmd/entire/cli/integration_test/hook_logging_test.go
index f78b070a..9b9c9472 100644
--- a/cmd/entire/cli/integration_test/hook_logging_test.go
+++ b/cmd/entire/cli/integration_test/hook_logging_test.go
@@ -147,3 +147,82 @@ func writeTestSessionStateForLogging(t *testing.T, repoDir, sessionID string) {
 		t.Fatalf("failed to write session state file: %v", err)
 	}
 }
+
+// TestRedactionDiagnostics_ReachEntireLog is the regression test for the
+// support report where a user could not tell whether their custom redaction
+// rules were loaded: the redact package logged through the process-default
+// slog logger (bare stderr — swallowed in hook contexts) because nothing
+// wires it to the CLI's .entire/logs/ logger, and the happy path logged
+// nothing at all. After the fix, a hook invocation must land two things in
+// .entire/logs/entire.log:
+//
+//  1. a component=redaction warning for a broken rule (here: an inline
+//     custom_redactions pattern that does not compile), and
+//  2. a load-time "redaction configured" summary line with rule counts,
+//     so "are my rules active?" is answerable from the log alone.
+func TestRedactionDiagnostics_ReachEntireLog(t *testing.T) {
+	t.Parallel()
+
+	env := NewFeatureBranchEnv(t)
+
+	env.PatchSettings(map[string]any{
+		"redaction": map[string]any{
+			"custom_redactions": map[string]any{
+				"good-rule":   "GOODRULE_[A-Z0-9]{4}",
+				"broken-rule": "BROKEN_[unclosed",
+			},
+		},
+	})
+	redactorsDir := filepath.Join(env.RepoDir, ".entire", "redactors")
+	if err := os.MkdirAll(redactorsDir, 0o755); err != nil {
+		t.Fatalf("mkdir redactors: %v", err)
+	}
+	packYAML := `name: acme
+version: 1.0.0
+rules:
+  - id: acme-token
+    regex: 'ACME_[A-Z0-9]{6}'
+`
+	if err := os.WriteFile(filepath.Join(redactorsDir, "acme.yaml"), []byte(packYAML), 0o644); err != nil {
+		t.Fatalf("write pack: %v", err)
+	}
+
+	// Any hook invocation initializes logging and configures redaction.
+	session := env.NewSession()
+	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
+		t.Fatalf("UserPromptSubmit: %v", err)
+	}
+
+	logPath := filepath.Join(env.RepoDir, ".entire", "logs", "entire.log")
+	data, err := os.ReadFile(logPath)
+	if err != nil {
+		t.Fatalf("read entire.log: %v", err)
+	}
+	log := string(data)
+
+	// Assert per-line so the component tag is proven on the diagnostic lines
+	// themselves — a log-wide substring check would let the summary line's
+	// component tag mask an untagged warning.
+	warnLine, summaryLine := "", ""
+	for _, line := range strings.Split(log, "\n") {
+		if strings.Contains(line, "skipping invalid custom_redactions pattern") {
+			warnLine = line
+		}
+		if strings.Contains(line, "redaction configured") {
+			summaryLine = line
+		}
+	}
+	if warnLine == "" {
+		t.Errorf("entire.log missing the compile-failure warning for the broken inline pattern")
+	} else if !strings.Contains(warnLine, `"component":"redaction"`) {
+		t.Errorf("compile-failure warning line is not tagged component=redaction: %s", warnLine)
+	}
+	if summaryLine == "" {
+		t.Errorf("entire.log missing the load-time 'redaction configured' summary line")
+	} else if !strings.Contains(summaryLine, `"component":"redaction"`) {
+		t.Errorf("summary line is not tagged component=redaction: %s", summaryLine)
+	}
+	if t.Failed() {
+		t.Logf("entire.log contents:\n%s", log)
+	}
+}
diff --git a/cmd/entire/cli/logging/logger.go b/cmd/entire/cli/logging/logger.go
index 08356679..1b1d0f81 100644
--- a/cmd/entire/cli/logging/logger.go
+++ b/cmd/entire/cli/logging/logger.go
@@ -139,6 +139,30 @@ func Init(ctx context.Context, sessionID string) error {
 	return nil
 }

+// Logger returns the active *slog.Logger so packages that cannot take a
+// context (e.g. redact) can be pointed at the same .entire/logs/ sink.
+// Returns slog.Default() only when Init has never run; Init's own stderr
+// fallback still sets the package logger, so callers get that JSON logger
+// rather than the default. Snapshot semantics: call after Init.
+func Logger() *slog.Logger {
+	mu.RLock()
+	defer mu.RUnlock()
+	if logger == nil {
+		return slog.Default()
+	}
+	return logger
+}
+
+// IsInitialized reports whether Init has set up a logger (including its
+// stderr fallback). Lets callers skip log lines that would otherwise fall
+// through to the process-default stderr logger and surface as terminal
+// noise in commands that never call Init.
+func IsInitialized() bool {
+	mu.RLock()
+	defer mu.RUnlock()
+	return logger != nil
+}
+
 // Close closes the log file if one is open.
 // Flushes any buffered data before closing.
 // Safe to call multiple times.
